macros.expression:
{% macro hash_relation_attributes(relation, table_alias='', exclude=[]) -%}
  {%- if execute -%}
    {%- set columns = adapter.get_columns_in_relation(relation) -%}
    {%- set selected = [] -%}
    {%- for column in columns | sort(attribute='name') -%}
      {%- if column.name | lower not in exclude | map('lower') | list -%}
        {%- set prefix = adapter.quote(table_alias) ~ '.' if table_alias else '' -%}
        {%- do selected.append('cast(' ~ prefix ~ adapter.quote(column.name) ~ ' as varchar)') -%}
      {%- endif -%}
    {%- endfor -%}
    {{ return("md5(to_json(list_value(" ~ selected | join(', ') ~ ")))" if selected else "md5('[]')") }}
  {%- else -%}
    cast(null as varchar)
  {%- endif -%}
{%- endmacro %}

{% macro round_money(expression, decimal_places=2) -%}
round({{ expression }}, {{ decimal_places }})
{%- endmacro %}

{% macro rounded_total(expressions, options={}) -%}
{{ round_money(expressions | join(' + '), options.get('decimal_places', 2)) }}
{%- endmacro %}

{% test nonnegative(model, column_name) %}
select *
from {{ model }}
where {{ column_name }} < 0
{% endtest %}

{% test unique_combination(model, columns) %}
select {{ columns | join(', ') }}, count(*) as duplicate_count
from {{ model }}
group by {{ columns | join(', ') }}
having count(*) > 1
{% endtest %}
